import{_ as i}from"./plugin-vue_export-helper-c27b6911.js";import{r as e,o as t,c as r,d as l,a as n,b as s,e as o,f as c}from"./app-500d1f03.js";const p="/assets/image-20220830193954123-b4c7fbc3.png",g="/assets/image-20220912151832904-0329b17c.png",d="/assets/image-20220912152315938-558dc461.png",u="/assets/IMG_20220902_143932_edit_140834443601946(1)-09720e1d.jpg",h="/assets/IMG_20220902_151417_edit_141665529465361-2c2bbd4f.jpg",_="/assets/image-20220902000343123-b641a838.png",f="/assets/image-20220902001250320-65ec3e11.png",m="/assets/image-20220912155415584-521090f9.png",I="/assets/image-20220912165902407-e308f2cb.png",O="/assets/1492928416812_4-73c5f62c.png",b="/assets/java-io-model-0-7a9158a1.png",k="/assets/1492929000361_5-958be645.png",y="/assets/java-io-model-1-8d03c5aa.png",x="/assets/1492929444818_6-b19d00e4.png",v="/assets/java-io-model-2-65267ea4.png",z="/assets/1492929553651_7-43398f12.png",w="/assets/java-io-model-3-f0bbf4d3.png",C="/assets/1492930243286_8-203c2b73.png",U="/assets/java-io-model-4-52ecd115.png",j={},q=n("p",null,"​ 今天看书的时候，又碰到了这个词条，每每网上搜这个，老感觉抓不到核心，总觉得差点意思，今天决定好好缕缕。",-1),N=n("h2",{id:"前言",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#前言","aria-hidden":"true"},"#"),s(" 前言")],-1),P={href:"https://www.zhihu.com/question/19732473/answer/241673170",target:"_blank",rel:"noopener noreferrer"},S=n("p",null,[s("进程级通信的维度讨论时， 阻塞和同步（非阻塞和异步）就是一对同义词， 且需要针对"),n("strong",null,"发送方"),s("和"),n("strong",null,"接收方"),s("作区分对待。"),n("br"),s(" 依据是《操作系统概念（第九版）》中有关进程间通信的部分：")],-1),B=n("img",{src:p,alt:"",loading:"lazy"},null,-1),E=n("br",null,null,-1),A={href:"https://www.zhihu.com/search?q=send&search_source=Entity&hybrid_search_source=Entity&hybrid_search_extra=%7B%22sourceType%22%3A%22answer%22%2C%22sourceId%22%3A241673170%7D",target:"_blank",rel:"noopener noreferrer"},V=n("strong",null,"阻塞的",-1),G=n("strong",null,"非阻塞的",-1),L=n("strong",null,"同步",-1),R=n("strong",null,"异步",-1),T=n("ul",null,[n("li",null,"阻塞式发送（blocking send）. 发送方进程会被一直阻塞， 直到消息被接受方进程收到。"),n("li",null,"非阻塞式发送（nonblocking send）。 发送方进程调用 send() 后， 立即就可以其他操作。"),n("li",null,"阻塞式接收（blocking receive） 接收方调用 receive() 后一直阻塞， 直到消息到达可用。"),n("li",null,"非阻塞式接受（nonblocking receive） 接收方调用 receive() 函数后， 要么得到一个有效的结果， 要么得到一个空值， 即不会被阻塞。")],-1),D=n("li",null,[n("p",null,[s("在 "),n("strong",null,"IO 系统调用"),s("层面（ IO system call ）层面， "),n("strong",null,"非阻塞 IO 系统调用"),s(" 和 "),n("strong",null,"异步 IO 系统调用"),s("存在着一定的差别， 它们都不会阻塞进程， 但是返回结果的方式和内容有所差别， 但是都属于非阻塞系统调用（ non-blocing system call ）")])],-1),J=c('<h2 id="同步与异步" tabindex="-1"><a class="header-anchor" href="#同步与异步" aria-hidden="true">#</a> 同步与异步</h2><p>​ 对于上面的第一点，即“进程级通信的维度讨论时， 阻塞和同步（非阻塞和异步）就是一对同义词”。我觉得这个可能不同出处，意见不同。不过往往提到“同步”与“异步”，我们想到的都是<strong>通信层面</strong>。现在我们暂且只论“同步”与“异步”：</p><p>​ 在《操作系统概念》第九版中，有如下一段：</p><figure><img src="'+g+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>我们再看在《深入理解操作系统》第三版中，对异常同步与异步的区分，可能会对这个概念更加清晰：</p><figure><img src="'+d+`" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这就很明晰了，<strong>异步信号是运行程序之外的事件产生，传递给其它线程（不限制个数）；同步信号则是运行程序产生，传递给产生这个信号的线程</strong>。通俗讲就是，我正在吃饭，异步信号就像这时有人叫我出去玩；同步信号就像我感受到自己吃饱了。</p><h2 id="阻塞与非阻塞" tabindex="-1"><a class="header-anchor" href="#阻塞与非阻塞" aria-hidden="true">#</a> 阻塞与非阻塞</h2><p>​ 而对于第二点，“在 <strong>IO 系统调用</strong>层面（ IO system call ）层面， <strong>非阻塞 IO 系统调用</strong> 和 <strong>异步 IO 系统调用</strong>存在着一定的差别”，其为了论证这一观点，有下面一段：</p><blockquote><p>​ 操作系统内核在执行 System Call 时， CPU 需要与 IO 设备完成一系列物理通信上的交互， 其实再一次会涉及到阻塞和非阻塞的问题， 例如， 操作系统发起了一个读硬盘的请求后， 其实是向硬盘设备通过总线发出了一个请求，它即可以阻塞式地等待IO 设备的返回结果，也可以非阻塞式的继续其他的操作。 在现代计算机中，这些物理通信操作基本都是异步完成的， 即发出请求后， 等待 I/O 设备的中断信号后， 再来读取相应的设备缓冲区 。 但是，大部分操作系统默认为用户级应用程序提供的都是阻塞式的系统调用 （blocking systemcall）接口， 因为阻塞式的调用，使得应用级代码的编写更容易（代码的执行顺序和编写顺序是一致的）。</p><pre><code>  但同样， 现在的大部分操作系统也会提供非阻塞I/O 系统调用接口（Nonblocking I/O system call）。  一个非阻塞调用不会挂起调用程序， 而是会立即返回一个值， 表示有多少bytes 的数据被成功读取（或写入）。
</code></pre><p>​ 非阻塞I/O 系统调用( nonblocking system call )的另一个替代品是 异步I/O系统调用 （asychronous system call）。 与非阻塞 I/O 系统调用类似，asychronous system call 也是会立即返回， 不会等待 I/O 操作的完成， 应用程序可以继续执行其他的操作， 等到 I/O 操作完成了以后，操作系统会通知调用进程（设置一个用户空间特殊的变量值 或者 触发一个 signal 或者 产生一个软中断 或者 调用应用程序的回调函数）。</p><p>​ 此处， 非阻塞I/O 系统调用( nonblocking system call ) 和 异步I/O系统调用 （asychronous system call）的区别是：</p><ul><li>一个非阻塞I/O 系统调用 read() 操作立即返回的是任何可以立即拿到的数据， 可以是完整的结果， 也可以是不完整的结果， 还可以是一个空值。</li><li>而异步I/O系统调用 read（）结果必须是完整的， 但是这个操作完成的通知可以延迟到将来的一个时间点。</li></ul></blockquote><p>​ 先不论上面对错，我觉得，<strong>非阻塞IO系统调用</strong>与<strong>异步IO系统调用</strong>更偏向于<strong>IO模型</strong>的范畴，不适合用来说“阻塞”与“非阻塞”。</p><hr><p>​ 我们最早接触到“阻塞”概念，一般是在学习进程基本状态时。比如《操作系统原理、实现与实践》中的“图3.7 进程的基本状态转移图”，展示了5种进程状态：<br><img src="`+u+'" alt="" loading="lazy"></p><ul><li>新建态（New）： 进程正在被创建.</li><li>就绪态（Ready）：进程在等待被操作系统调度</li><li>运行态（Running）：进程的指令正在被执行</li><li>阻塞态（Waiting）： 进程正在等待一些事件的发生（例如 I/O 的完成或者收到某个信号）</li><li>退出态（Terminated）： 进程执行完毕（可能是被强行终止的）</li></ul><p>​ <strong>所以我们通常说的“阻塞”与“非阻塞”，可以类比一个进程。当一个进程在执行过程中，发出了一个写磁盘指令，此时这个进程由于等待事件进入阻塞态（就是此进程放入了阻塞队列，等到不用等待时，会再放入就绪队列）。</strong></p><figure><img src="'+h+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>​ 那么进程为什么要放进阻塞队列，在原来的地方一直等着不好吗？原因是，同一CPU，某一时间点，最多只能执行一个进程（或者线程）。如果这个进程被阻塞了，就把CPU给让出来呀，让其它等着执行的进程得以执行呀。这样可以提高CPU的利用率。</p><blockquote><p>补充：</p><p>多进程切换的时机就是CPU出现空闲的时间点，这个空闲点也被称为<strong>调度点</strong>。产生情况：</p><ul><li>当前进程执行过程中产生： <ul><li>如执行了需要CPU等待的指令，（如启动磁盘读写等），此时当前进程进入阻塞态。</li><li>当前进程执行了exit()退出时</li><li>比如0号进程在时刻48调用fork()创建了1号进程，<br> 时刻49:1号进程被放到就绪队列；0号进程执行pause()，从运行态变成就绪态，让出CPU</li><li>......</li></ul></li><li>操作系统硬性加入： <ul><li>如给每个进程分配一个时间片，当前进程时间片用完时</li><li>......</li></ul></li></ul></blockquote><h2 id="i-o" tabindex="-1"><a class="header-anchor" href="#i-o" aria-hidden="true">#</a> I/O</h2><h3 id="什么是i-o" tabindex="-1"><a class="header-anchor" href="#什么是i-o" aria-hidden="true">#</a> 什么是I/O</h3><p>先看一下什么是系统级IO：</p><p>​ 在《深入理解计算机系统》第三版中，可以看到下面一段：</p><figure><img src="'+_+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>​ 我们可以理解为<strong>系统级I/O</strong>就是<strong>由系统内核提供的I/O函数，用于实现主存与外部设备（如磁盘驱动器、终端和网络）之间的数据复制功能。<strong>而我们平时使用的高级语言，如C++的I/O功能，底层是对系统级IO的封装。（我们的</strong>应用程序一般处于用户态，而处于用户态的进程有诸多限制（如不能进行 I/O 操作），所以有些功能必须由内核代劳完成</strong>。而内核就是通过向应用层提供 <code>系统调用</code>，来完成一些在用户态不能完成的工作。）</p><p>​ 我们可以看一下这个关系：（其中“标准I/O函数”是C语言定义的一组高级输入输出函数（实际上也还是对系统级I/O的封装），“RIO函数”是《深入理解计算机系统》作者自己写的一个I/O库。）</p><figure><img src="'+f+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>​ 那么，什么是<strong>I/O系统调用</strong>？就是<strong>进程对I/O函数的调用</strong>呗。别管什么语言的IO调用，<strong>最终都会转换为</strong>对<strong>系统级I/O函数</strong>的<strong>调用</strong>。</p><h3 id="i-o的工作模式" tabindex="-1"><a class="header-anchor" href="#i-o的工作模式" aria-hidden="true">#</a> I/O的工作模式</h3><p>当我在维基百科上对<code>I/O</code>这个词条搜索时，看到下面一段：</p><figure><img src="'+m+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>至此，<strong>同步与异步侧重于调用者，同步是调用者主动等待调用结果，其中线程分为挂起与不挂起；异步是调用者立即去做别的事情，被调用者通知”调用者。“</strong></p><h2 id="io模型" tabindex="-1"><a class="header-anchor" href="#io模型" aria-hidden="true">#</a> IO模型</h2><p>一个输入操作通常包括两个阶段:</p><ul><li>等待数据准备好</li><li>从内核向进程复制数据</li></ul><p>比如对于一个<strong>套接字</strong>上的输入操作：</p><ul><li>第一步：通常涉及等待数据从网络中到达。当所等待分组到达时，它被复制到<strong>内核</strong>中的某个缓冲区。</li><li>第二步：就是把数据从内核缓冲区复制到<strong>应用进程</strong>缓冲区。</li></ul><hr><p>下图分别对应 <strong>Unix 的五种 I/O 模型</strong>:：</p><ul><li>阻塞式 I/O（BIO）</li><li>非阻塞式 I/O(NIO)</li><li>I/O 复用(select 和 poll)</li><li>信号驱动式 I/O(SIGIO)</li><li>异步 I/O(AIO)</li></ul><figure><img src="'+I+`" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><hr><p><strong>Unix 的五种 I/O 模型的同步与异步：</strong></p><ul><li>同步 I/O: 应用进程在调用 recvfrom 操作时<strong>会</strong>阻塞（即第二步时会阻塞）。</li><li>异步 I/O: 应用进程在调用 recvfrom 操作时<strong>不会</strong>阻塞。</li></ul><p>同步 I/O：</p><p>​ 阻塞式 I/O、非阻塞式 I/O、I/O 复用和信号驱动 I/O 。</p><blockquote><p>虽然非阻塞式 I/O 和信号驱动 I/O 在等待数据阶段不会阻塞，但是在之后的将数据从内核复制到应用进程这个操作会阻塞。</p></blockquote><h3 id="阻塞式-i-o" tabindex="-1"><a class="header-anchor" href="#阻塞式-i-o" aria-hidden="true">#</a> 阻塞式 I/O</h3><p>应用进程被阻塞，直到数据<strong>复制到</strong>应用进程缓冲区中<strong>才返回</strong>。</p><p>应该注意到，在阻塞的过程中，其它程序还可以执行，因此阻塞<strong>不意味着整个操作系统都被阻塞</strong>。因为其他程序还可以执行，因此<strong>不消耗 CPU 时间，这种模型的执行效率会比较高</strong>。</p><p>下图中，recvfrom 用于接收 Socket 传来的数据，并复制到应用进程的缓冲区 buf 中（即第二步）。这里把 recvfrom() 当成系统调用。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token class-name">ssize_t</span> <span class="token function">recvfrom</span><span class="token punctuation">(</span><span class="token keyword">int</span> sockfd<span class="token punctuation">,</span> <span class="token keyword">void</span> <span class="token operator">*</span>buf<span class="token punctuation">,</span> <span class="token class-name">size_t</span> len<span class="token punctuation">,</span> <span class="token keyword">int</span> flags<span class="token punctuation">,</span> <span class="token keyword">struct</span> <span class="token class-name">sockaddr</span> <span class="token operator">*</span>src_addr<span class="token punctuation">,</span> <span class="token class-name">socklen_t</span> <span class="token operator">*</span>addrlen<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><figure><img src="`+O+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或者网友提供的</p><figure><img src="'+b+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="非阻塞式-i-o" tabindex="-1"><a class="header-anchor" href="#非阻塞式-i-o" aria-hidden="true">#</a> 非阻塞式 I/O</h3><p>应用进程执行系统调用之后，内核返回一个错误码。应用进程可以继续执行，但是需要不断的执行系统调用来获知 I/O 是否完成，这种方式称为**轮询 **( polling )。</p><p>由于 CPU 要处理更多的系统调用，因此这种模型是比较<strong>低效</strong>的。</p><figure><img src="'+k+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或者网友提供的</p><figure><img src="'+y+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="i-o-复用" tabindex="-1"><a class="header-anchor" href="#i-o-复用" aria-hidden="true">#</a> I/O 复用</h3><p>使用 select 或者 poll 等待数据，并且可以<strong>等待多个套接字</strong>中的<strong>任何一个</strong>变为可读，这一过程会被阻塞，当某一个套接字可读时返回。之后再使用 recvfrom 把数据从内核复制到进程中。</p><p>它可以让单个进程具有处理多个 I/O 事件的能力。又被称为 Event Driven I/O，即事件驱动 I/O。</p><p>如果一个 Web 服务器没有 I/O 复用，那么每一个 Socket 连接都需要创建一个线程去处理。如果同时有几万个连接，那么就需要创建相同数量的线程。并且相比于多进程和多线程技术，I/O 复用不需要进程线程创建和切换的开销，系统开销更小。</p><figure><img src="'+x+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或者网友提供的</p><figure><img src="'+v+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="信号驱动-i-o" tabindex="-1"><a class="header-anchor" href="#信号驱动-i-o" aria-hidden="true">#</a> 信号驱动 I/O</h3><p>应用进程使用 sigaction 系统调用，内核立即返回，应用进程可以继续执行，也就是说等待数据阶段应用进程是非阻塞的。内核在数据到达时向应用进程发送 SIGIO 信号，应用进程收到之后在信号处理程序中调用 recvfrom 将数据从内核复制到应用进程中。</p><p>相比于非阻塞式 I/O 的轮询方式，信号驱动 I/O 的 CPU 利用率更高。</p><figure><img src="'+z+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或者网友提供的</p><figure><img src="'+w+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="异步-i-o" tabindex="-1"><a class="header-anchor" href="#异步-i-o" aria-hidden="true">#</a> 异步 I/O</h3><p>进行 aio_read 系统调用会立即返回，应用进程继续执行，不会被阻塞，内核会在所有操作完成之后向应用进程发送信号。</p><p>异步 I/O 与信号驱动 I/O 的区别在于，异步 I/O 的信号是<strong>通知应用进程 I/O 完成</strong>，而信号驱动 I/O 的信号是通知应用进程可以开始 I/O。</p><figure><img src="'+C+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或者网友提供的</p><figure><img src="'+U+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="参考链接" tabindex="-1"><a class="header-anchor" href="#参考链接" aria-hidden="true">#</a> 参考链接</h2>',80),M={href:"https://zh.wikipedia.org/zh-cn/I/O",target:"_blank",rel:"noopener noreferrer"},W={href:"https://developer.mozilla.org/zh-CN/docs/Learn/JavaScript/Asynchronous/Introducing",target:"_blank",rel:"noopener noreferrer"},F={href:"https://www.zhihu.com/question/19732473/answer/241673170",target:"_blank",rel:"noopener noreferrer"},H={href:"https://pdai.tech/md/java/io/java-io-model.html",target:"_blank",rel:"noopener noreferrer"};function K(Q,X){const a=e("ExternalLinkIcon");return t(),r("div",null,[q,l(" more "),N,n("p",null,[s("在知乎上看到这样一个"),n("a",P,[s("观点"),o(a)]),s("：")]),n("blockquote",null,[n("ul",null,[n("li",null,[S,n("p",null,[B,E,s(" 翻译一下就是：进程间的通信是通过 "),n("a",A,[s("send"),o(a)]),s("() 和 receive() 两种基本操作完成的。具体如何实现这两种基础操作，存在着不同的设计。 消息的传递有可能是"),V,s("或"),G,s(" – 也被称为"),L,s("或"),R,s("的：")]),T]),D])]),J,n("ul",null,[n("li",null,[n("p",null,[n("a",M,[s("https://zh.wikipedia.org/zh-cn/I/O"),o(a)])])]),n("li",null,[n("p",null,[n("a",W,[s("https://developer.mozilla.org/zh-CN/docs/Learn/JavaScript/Asynchronous/Introducing"),o(a)])])]),n("li",null,[n("p",null,[n("a",F,[s("https://www.zhihu.com/question/19732473/answer/241673170"),o(a)])])]),n("li",null,[n("p",null,[n("a",H,[s("https://pdai.tech/md/java/io/java-io-model.html"),o(a)])])])])])}const $=i(j,[["render",K],["__file","061synchronous_asynchronous_blocking_non-blocking_io.html.vue"]]);export{$ as default};
